# Broker: |an idempotent retry is written once| [cluster] — ../src/contract.lawspec:101
# A producer with an id stamps each batch with its epoch and sequence. A
# retry of a batch the partition already has gives the first write's
# offset and writes nothing.
# References: KIP-98
# for all (t :: Text) (batch :: List (lawtwin.kafka.model::type::Record)) => created t 1
# implies let tp = let _lawspecRecordField0 = t in let _lawspecRecordField1 = 0 in
# lawtwin.kafka.model::type::TopicPartition::TopicPartition(_lawspecRecordField0,
# _lawspecRecordField1) in let it = attempt (initProducerIdRequest (Maybe::Absent())) in
# match (it) { Either::Left _lawspecSelection0x0 -> false; Either::Right
# _lawspecSelection0x0 -> let tag = Maybe::Present(tagOf _lawspecSelection0x0 0) in let
# first = attempt (produceRequest tp tag batch) in let retry = attempt (produceRequest
# tp tag batch) in ((first == retry) And followsBatch first batch (attempt
# (listOffsetsRequest tp (lawtwin.kafka.model::type::OffsetSpec::Latest())
# (lawtwin.kafka.model::type::IsolationLevel::ReadUncommitted())))) } = true end for all
# Broker: |an idempotent retry is written once| [cluster], finite cases —
# ../src/contract.lawspec:101
def _check_broker_an_idempotent_retry_is_written_once_2(_case_values, _case_context):
    symbols = {}
    _lawspec_shared_cluster = _abilities.Cluster(symbols)
    ls.install_handlers(
        symbols,
        {"lawtwin.kafka::ability::Broker": _lawspec_shared_cluster},
    )
    t = _case_values[0](symbols)
    batch = _case_values[1](symbols)
    _assert_broker_an_idempotent_retry_is_written_once_2(
        _case_context,
        symbols,
        t,
        batch,
    )


_cases_broker_an_idempotent_retry_is_written_once_2 = ls.register_finite_cases(
    globals(),
    "test_broker_an_idempotent_retry_is_written_once_2_",
    [
        [
            [0, [lambda symbols: "o"]],
            [[[0, [lambda symbols: _literal_value_6(symbols)]], 1]],
        ],
        [
            [0, [lambda symbols: "t"]],
            [[[0, [lambda symbols: _literal_value_7(symbols)]], 1]],
        ],
        [
            [0, [lambda symbols: "7oIEcKM"]],
            [[[0, [lambda symbols: _literal_value_8(symbols)]], 1]],
        ],
        [
            [0, [lambda symbols: "ucnH_8"]],
            [[[0, [lambda symbols: _literal_value_9(symbols)]], 1]],
        ],
    ],
    _check_broker_an_idempotent_retry_is_written_once_2,
    "lawtwin.kafka::Broker: |an idempotent retry is written once| [cluster]",
)


