# _lawspecRecordField1) in let it = attempt (initProducerIdRequest
# (Maybe::Present(txid))) in match (it) { Either::Left _lawspecSelection0x0 -> false;
# Either::Right _lawspecSelection0x0 -> let it = attempt (initProducerIdRequest
# (Maybe::Present(txid))) in match (it) { Either::Left _match__lawspecSelection0x0_0 ->
# false; Either::Right _match__lawspecSelection0x0_0 -> ((fencedBy _lawspecSelection0x0
# _match__lawspecSelection0x0_0 And match (attempt (addPartitionsToTxnRequest txid
# (match (_lawspecSelection0x0) {
# lawtwin.kafka.model::type::ProducerIdAndEpoch::ProducerIdAndEpoch
# lawspecFieldproducerId lawspecFieldproducerEpoch -> lawspecFieldproducerId }) (match
# (_lawspecSelection0x0) {
# lawtwin.kafka.model::type::ProducerIdAndEpoch::ProducerIdAndEpoch
# lawspecFieldproducerId lawspecFieldproducerEpoch -> lawspecFieldproducerEpoch })
# (List::Cons(tp, List::Nil())))) { Either::Left lawspecFailure -> let it =
# lawspecFailure in match (it) { lawtwin.kafka.model::type::KafkaError::ProducerFenced
# -> true; lawtwin.kafka.model::type::KafkaError::UnknownTopicOrPartition -> false;
