# GroupCoordinator: |a heartbeat from an older generation asks the member to rejoin|
# [cluster] — ../src/contract.lawspec:1544
# A rebalance moves the group to a new generation. A member at the old
# one is told so on its next heartbeat; when it rejoins with the same
# subscription it learns the new generation without starting another.
# for all (t :: Text) (g :: Text) (one :: Text) (other :: Text) => created t 1 implies
# let it = attempt (joinGroup g one (List::Cons(t, List::Nil()))) in match (it) {
# Either::Left _lawspecSelection0x0 -> false; Either::Right _lawspecSelection0x0 -> let
# new = attempt (joinGroup g other (List::Cons(t, List::Nil()))) in (match (attempt
# (heartbeat g one _lawspecSelection0x0)) { Either::Left lawspecFailure -> let it =
# lawspecFailure in match (it) {
# lawtwin.kafka.model::type::KafkaError::IllegalGeneration -> true;
# lawtwin.kafka.model::type::KafkaError::UnknownTopicOrPartition -> false;
# lawtwin.kafka.model::type::KafkaError::TopicAlreadyExists -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidTopic -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidPartitions -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidRecord -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidRequest -> false;
# lawtwin.kafka.model::type::KafkaError::OffsetOutOfRange -> false;
# lawtwin.kafka.model::type::KafkaError::OutOfOrderSequenceNumber -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidProducerEpoch -> false;
# lawtwin.kafka.model::type::KafkaError::ProducerFenced -> false;
# lawtwin.kafka.model::type::KafkaError::UnknownProducerId -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidProducerIdMapping -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidTxnState -> false;
# lawtwin.kafka.model::type::KafkaError::InvalidGroupId -> false;
# lawtwin.kafka.model::type::KafkaError::UnknownMemberId -> false;
# lawtwin.kafka.model::type::KafkaError::IllegalState -> false }; Either::Right
# lawspecResult -> false } And let it = attempt (joinGroup g one (List::Cons(t,
# List::Nil()))) in match (it) { Either::Left _match__lawspecSelection0x0_0 -> false;
# Either::Right _match__lawspecSelection0x0_0 -> ((new ==
# Either::Right(_match__lawspecSelection0x0_0)) And match (attempt (heartbeat g one
# _match__lawspecSelection0x0_0)) { Either::Left railwayError0 -> false; Either::Right
# railwayValue1 -> true }) }) } = true end for all
