def _lawspec_case_groupcoordinator_a_heartbeat_from_an_older_2(_values):
    symbols = {}
    _lawspec_shared_cluster = _abilities.Cluster(symbols)
    ls.install_handlers(
        symbols,
        {
            "lawtwin.kafka::ability::GroupCoordinator": _lawspec_shared_cluster,
            "lawtwin.kafka::ability::Broker": _lawspec_shared_cluster,
        },
    )
    t = ls.convert(_values[0], "Text", MACHINE_BITS)
    g = ls.convert(_values[1], "Text", MACHINE_BITS)
    one = ls.convert(_values[2], "Text", MACHINE_BITS)
    other = ls.convert(_values[3], "Text", MACHINE_BITS)
    if not (
        _definitions.lawtwin_kafka_model_valid_topic_name(symbols, t)
        and ls.binary("!=", g, "", "Text", "Text")
        and ls.binary("!=", one, "", "Text", "Text")
        and (
            ls.binary("!=", other, "", "Text", "Text")
            and ls.binary("!=", other, one, "Text", "Text")
        )
    ):
        return None
    _assert_groupcoordinator_a_heartbeat_from_an_older_2(
        "lawtwin.kafka::GroupCoordinator: |a heartbeat from an older generation asks the member to rejoin| [cluster] search",
        symbols,
        t,
        g,
        one,
        other,
    )
    return 0


